interface IconProps {
  className?: string;
}

const createIcon = (
  viewBox: string,
  paths: string[],
  defaultClassName?: string,
) => {
  return ({ className = defaultClassName }: IconProps) => (
    <svg
      className={className}
      fill="none"
      stroke="currentColor"
      viewBox={viewBox}
    >
      {paths.map((path, index) => (
        <path
          key={index}
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeWidth={2}
          d={path}
        />
      ))}
    </svg>
  );
};

const createIconWithFill = (
  viewBox: string,
  paths: string[],
  defaultClassName?: string,
) => {
  return ({ className = defaultClassName }: IconProps) => (
    <svg className={className} viewBox={viewBox} fill="none">
      {paths.map((path, index) => (
        <path
          key={index}
          stroke="currentColor"
          strokeWidth={2}
          strokeLinecap="round"
          strokeLinejoin="round"
          d={path}
        />
      ))}
    </svg>
  );
};

